import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  let mesh = null;
  let loadedScene = null;
  let hoverTimeline = null;
  let pressTimeline = null;
  let originalEmissive = null;

  // Start loading GLB
  const loadPromise = ctx.glbLoader.loadGLB(config.meshUrl);
  loadPromise.then((gltf) => {
    loadedScene = gltf.scene || gltf;
    group.add(loadedScene);

    // Assume first mesh is the card
    loadedScene.traverse((child) => {
      if (child.isMesh) {
        mesh = child;
        // Save original emissive for restoration
        if (mesh.material) {
          originalEmissive = mesh.material.emissive ? mesh.material.emissive.clone() : new ctx.THREE.Color(0x000000);
        }
        // Ensure material is node material for smooth transition (optional)
        // Keep original material as is
      }
    });
  }).catch(() => {
    // Silent fail – fallback to invisible placeholder
  });

  // ===== Interactions =====
  const handlers = {
    hover: {
      enter: () => {
        if (!mesh) return;
        gsap.killTweensOf(mesh.material.emissive);
        hoverTimeline = gsap.timeline();
        hoverTimeline
          .to(group.position, { y: group.position.y + 0.15, duration: 0.3, ease: 'power2.out' })
          .to(mesh.material.emissive, { r: 1, g: 0.165, b: 0.22, duration: 0.2, ease: 'power2.out' }, 0) // accent #ff2a38
          .set(mesh.material, { needsUpdate: true }, 0);
      },
      leave: () => {
        if (!mesh) return;
        gsap.killTweensOf(mesh.material.emissive);
        hoverTimeline = gsap.timeline();
        hoverTimeline
          .to(group.position, { y: group.position.y - 0.15, duration: 0.3, ease: 'power2.out' })
          .to(mesh.material.emissive, {
            r: originalEmissive.r,
            g: originalEmissive.g,
            b: originalEmissive.b,
            duration: 0.2,
            ease: 'power2.out'
          }, 0)
          .set(mesh.material, { needsUpdate: true }, 0);
      }
    },
    click: {
      press: () => {
        if (!mesh) return;
        gsap.killTweensOf(group.scale);
        pressTimeline = gsap.timeline();
        pressTimeline
          .to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' })
          .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out', delay: 0.05 })
          .eventCallback('onStart', () => {
            ctx.emit('hub-home.select');
          });
      }
    }
  };

  group.userData.handlers = handlers;

  // ===== Cinematic Primitive =====
  const primitiveResult = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });

  // ===== Cleanup =====
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();

    // Dispose GLB resources
    if (loadedScene) {
      loadedScene.traverse((child) => {
        if (child.isMesh) {
          if (child.material) {
            child.material.dispose();
          }
          if (child.geometry) {
            child.geometry.dispose();
          }
        }
      });
    }

    // Primitive cleanup
    if (primitiveResult && typeof primitiveResult.cleanup === 'function') {
      primitiveResult.cleanup();
    }
  };

  return group;
}
